// Generates web/css/packs.css and web/js/iconData.js from the ChatGPT design kit in design/stepup/ (single source of truth).
// Run: npm run design   (a unit test fails when the generated files are out of date).
import { readFileSync, writeFileSync, copyFileSync, mkdirSync } from 'node:fs';
const tokens = JSON.parse(readFileSync('design/stepup/tokens.json', 'utf8'));
const DEFAULT = 'momentum';
const vars = (t) => Object.entries(t).map(([k, v]) => `--${k.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase())}:${v}`).join(';');
let css = '/* GENERATED by scripts/build-design.mjs from design/stepup/tokens.json - do not edit. */\n';
for (const [name, m] of Object.entries(tokens)) {
  const pack = name === DEFAULT ? ':not([data-pack])' : `[data-pack="${name}"]`;
  css += `:root${pack}{${vars(m.light)}}\n`;
  css += `@media (prefers-color-scheme:dark){:root${pack}:not([data-theme="light"]){${vars(m.dark)}}}\n`;
  css += `:root${pack}[data-theme="dark"]{${vars(m.dark)}}\n`;
}
writeFileSync('web/css/packs.css', css);
// Icons as data: a small tree of whitelisted drawing elements and attributes (g, path, circle, rect, ...), drawn with createElementNS: no innerHTML anywhere.
import { readdirSync } from 'node:fs';
const OK_TAGS = new Set(['g', 'path', 'circle', 'ellipse', 'rect', 'line', 'polyline', 'polygon']);
const OK_ATTRS = new Set(['d', 'cx', 'cy', 'r', 'rx', 'ry', 'x', 'y', 'x1', 'y1', 'x2', 'y2', 'width', 'height', 'points', 'fill', 'stroke', 'stroke-width', 'stroke-linecap', 'stroke-linejoin', 'transform', 'opacity', 'fill-rule', 'clip-rule', 'fill-opacity', 'stroke-opacity', 'class']); // class: only the m-<part> hooks the motion CSS animates
const VALUE = /^[\w\s.,#()%-]*$/; // no quotes, urls, scripts
function parseSvg(src) { // minimal parser for the generated kit: <tag attrs/>, <tag attrs>...</tag>
  const root = { children: [] }, stack = [root];
  for (const m of src.replace(/^<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '').matchAll(/<(\/?)([a-zA-Z]+)([^>]*?)(\/?)>/g)) {
    const [, close, tag, rest, selfClose] = m;
    if (close) { stack.pop(); continue; }
    if (!OK_TAGS.has(tag)) throw new Error(`icon element not allowed: ${tag}`);
    const attrs = {}; for (const a of rest.matchAll(/([\w-]+)="([^"]*)"/g)) { if (!OK_ATTRS.has(a[1]) || !VALUE.test(a[2])) throw new Error(`icon attribute not allowed: ${a[1]}="${a[2]}"`); attrs[a[1]] = a[2].trim(); }
    const node = [tag, attrs, []]; stack[stack.length - 1].children.push(node); if (!selfClose) stack.push({ children: node[2] });
  }
  return root.children;
}
const icons = {};
for (const f of readdirSync('design/stepup/svg').filter((n) => n.startsWith('ui-'))) icons[f.slice(3, -4)] = parseSvg(readFileSync(`design/stepup/svg/${f}`, 'utf8'));
// Characters (walk / run on a round plate, 96 and 200, light and dark) and the speed / pace gauges: the same whitelisted data, drawn inline so the CSS can animate their m-* parts.
const figures = {};
for (const [dir, files] of [['characters', ['walk-96', 'walk-200', 'run-96', 'run-200']], ['gauges', ['gauge-speed', 'gauge-pace']]]) for (const n of files) for (const mode of ['light', 'dark']) { const src = readFileSync(`design/stepup/round8/${dir}/${n}-${mode}.svg`, 'utf8'); figures[`${n}-${mode}`] = { vb: /viewBox="([\d .]+)"/.exec(src)[1], nodes: parseSvg(src) }; }
writeFileSync('web/js/figureData.js', `// GENERATED by scripts/build-design.mjs from design/stepup/round8/ - do not edit.\nexport const FIGURES = ${JSON.stringify(figures)};\n`);
writeFileSync('web/js/iconData.js', `// GENERATED by scripts/build-design.mjs from design/stepup/svg/ui-*.svg - do not edit.\nexport const ICONS = ${JSON.stringify(icons)};\n`);

// ---- Brand: web icon, maskable icon, brand data (mark + wordmark paths for inline drawing), Android launcher PNGs ----
const svgOf = (n) => readFileSync(`design/stepup/svg/${n}.svg`, 'utf8').trim();
writeFileSync('web/icon.svg', svgOf('app-icon') + '\n');
const inner = (n) => svgOf(n).replace(/^<svg[^>]*>/, '').replace(/<\/svg>$/, '');
writeFileSync('web/icons/logo-maskable.svg', `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 108 108">${inner('brand-adaptive-background')}${inner('brand-adaptive-foreground')}</svg>\n`);
const parts = (n) => [...svgOf(n).matchAll(/<(path|circle)\b([^>]*?)\/>/g)].map(([, tag, a]) => [tag, Object.fromEntries([...a.matchAll(/([\w-]+)="([^"]*)"/g)].map((m) => [m[1], m[2]])) ]);
// the symbol is filled in three colours (hills, sun): each shape gets a role class so the app can colour it from the pack tokens
const ROLE = { '#006B60': 'bm-a', '#216B39': 'bm-b', '#865000': 'bm-c' };
const mark = parts('brand-mark').map(([t, a]) => [t, { ...Object.fromEntries(Object.entries(a).filter(([k]) => ['d', 'cx', 'cy', 'r'].includes(k))), class: ROLE[a.fill] || 'bm-a' }]);
const word = parts('brand-wordmark');
const wordSvg = svgOf('brand-wordmark'), wordShift = /<g transform="translate\(([\d.\- ]+)\)"/.exec(wordSvg)[1], wordView = /viewBox="([^"]+)"/.exec(wordSvg)[1], wordStroke = /stroke-width="([^"]+)"/.exec(wordSvg)[1];
writeFileSync('web/js/brandData.js', `// GENERATED by scripts/build-design.mjs from design/stepup/svg (brand-mark, brand-wordmark) - do not edit.\nexport const MARK = ${JSON.stringify(mark)};\nexport const WORD = ${JSON.stringify(word.map(([t, a]) => [t, a])) };\nexport const WORD_SHIFT = ${JSON.stringify(wordShift)}, WORD_VIEW = ${JSON.stringify(wordView)}, WORD_STROKE = ${JSON.stringify(wordStroke)};\n`);
const DENS = [['mdpi', 108, 48], ['hdpi', 162, 72], ['xhdpi', 216, 96], ['xxhdpi', 324, 144], ['xxxhdpi', 432, 192]];
for (const [d, fg, legacy] of DENS) {
  const dir = `android/app/src/main/res/mipmap-${d}`; mkdirSync(dir, { recursive: true });
  copyFileSync(`design/stepup/platform/android-adaptive-foreground-${fg}.png`, `${dir}/ic_launcher_foreground.png`);
  copyFileSync(`design/stepup/platform/android-legacy-${legacy}.png`, `${dir}/ic_launcher.png`);
}
console.log(`design ok (${Object.keys(tokens).length} packs, ${Object.keys(icons).length} icons, brand)`);
